<?php  use App\Models\ProfilDonatur; use App\Models\ProfilPegawai; use App\Models\User;  test('profile page is displayed', function () {     $user = User::factory()->create([         'role' => 'admin',         'status' => 'aktif',     ]);     ProfilPegawai::create([         'user_id' => $user->id,         'nama' => 'Admin Profile',         'jabatan' => 'Admin',     ]);      $response = $this->actingAs($user)->get(route('profile.edit'));      $response->assertOk();     $response->assertSee('Admin Profile'); });  test('pegawai profile information can be updated', function () {     $user = User::factory()->create([         'role' => 'admin',         'status' => 'aktif',     ]);     ProfilPegawai::create([         'user_id' => $user->id,         'nama' => 'Admin Lama',         'jabatan' => 'Admin',     ]);      $response = $this->actingAs($user)->patch(route('profile.update'), [         'nama' => 'Admin Baru',         'username' => 'admin.baru',         'email' => 'adminbaru@example.com',         'jabatan' => 'Admin Utama',         'no_hp' => '081234567899',         'alamat' => 'Jl. Mawar No. 12',     ]);      $response->assertSessionHasNoErrors();     $response->assertRedirect(route('profile.edit'));     $response->assertSessionHas('status', 'profile-updated');      $this->assertDatabaseHas('users', [         'id' => $user->id,         'username' => 'admin.baru',         'email' => 'adminbaru@example.com',     ]);      $this->assertDatabaseHas('profil_pegawai', [         'user_id' => $user->id,         'nama' => 'Admin Baru',         'jabatan' => 'Admin Utama',         'no_hp' => '081234567899',     ]); });  test('donatur profile information can be updated', function () {     $user = User::factory()->create([         'role' => 'donatur',         'status' => 'aktif',     ]);     ProfilDonatur::create([         'user_id' => $user->id,         'nama' => 'Donatur Lama',     ]);      $response = $this->actingAs($user)->patch(route('profile.update'), [         'nama' => 'Donatur Baru',         'username' => 'donatur.baru',         'email' => 'donaturbaru@example.com',         'no_hp' => '085555555555',         'alamat' => 'Jl. Kenanga No. 3',     ]);      $response->assertSessionHasNoErrors();     $response->assertRedirect(route('profile.edit'));      $this->assertDatabaseHas('users', [         'id' => $user->id,         'username' => 'donatur.baru',         'email' => 'donaturbaru@example.com',     ]);      $this->assertDatabaseHas('profil_donatur', [         'user_id' => $user->id,         'nama' => 'Donatur Baru',         'no_hp' => '085555555555',     ]); });  test('user can delete their account', function () {     $user = User::factory()->create();      $response = $this->actingAs($user)->delete(route('profile.destroy'), [         'password' => 'password',     ]);      $response->assertSessionHasNoErrors();     $response->assertRedirect('/');      $this->assertGuest();     $this->assertDatabaseMissing('users', [         'id' => $user->id,     ]); });  test('correct password must be provided to delete account', function () {     $user = User::factory()->create();      $response = $this->actingAs($user)->from(route('profile.edit'))->delete(route('profile.destroy'), [         'password' => 'wrong-password',     ]);      $response->assertSessionHasErrorsIn('userDeletion', 'password');     $response->assertRedirect(route('profile.edit'));      $this->assertNotNull($user->fresh()); });